using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using Ohmline.Charging.Client.Contracts.ReadModels;
using Ohmline.Mobile.Core.Api;

namespace Ohmline.Mobile.Core.Listings;

/// <summary>
/// The app's first screen (section 19.4): a charge point's listing, as drivers see it. The
/// properties and the command are generated by CommunityToolkit.Mvvm from the partial
/// declarations below, so the page binds to <c>Listing</c>, <c>IsLoading</c>, <c>Message</c> and
/// <c>LoadCommand</c>.
/// </summary>
public sealed partial class ChargePointListingViewModel(ChargingApiClient api) : ObservableObject
{
    /// <summary>The charge point to show, as printed on it: <c>OHM-SLC-0042</c>.</summary>
    [ObservableProperty]
    public partial string ChargePointId { get; set; } = "";

    [ObservableProperty]
    public partial ChargePointListingDto? Listing { get; set; }

    [ObservableProperty]
    public partial bool IsLoading { get; set; }

    /// <summary>What to tell the driver instead of a listing, in the app's words.</summary>
    [ObservableProperty]
    public partial string? Message { get; set; }

    [RelayCommand]
    private async Task LoadAsync(CancellationToken cancellationToken)
    {
        IsLoading = true;
        Message = null;
        try
        {
            Listing = await api.GetListingAsync(ChargePointId.Trim(), cancellationToken);
            Message = Listing is null ? $"{ChargePointId} is not listed yet." : null;
        }
        catch (HttpRequestException)
        {
            Message = "Ohmline cannot be reached. Check your connection and try again.";
        }
        finally
        {
            IsLoading = false;
        }
    }
}
